import products from './products.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search products by name (case-insensitive substring match).',
      inputSchema: {
        type: 'object',
        properties: {
          query: {
            type: 'string',
            description: 'Substring to search for in product names.'
          },
          limit: {
            type: 'integer',
            minimum: 1,
            maximum: 10,
            description: 'Maximum number of results to return (1-10).'
          }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function validateInventorySearchArgs(args) {
  if (!isPlainObject(args)) {
    throw new Error('Invalid arguments: expected an object');
  }
  if (typeof args.query !== 'string') {
    throw new Error('Invalid arguments: "query" must be a string');
  }
  if (args.limit !== undefined) {
    if (typeof args.limit !== 'number' || !Number.isInteger(args.limit)) {
      throw new Error('Invalid arguments: "limit" must be an integer');
    }
    if (args.limit < 1 || args.limit > 10) {
      throw new Error('Invalid arguments: "limit" must be between 1 and 10');
    }
  }
  for (const key of Object.keys(args)) {
    if (key !== 'query' && key !== 'limit') {
      throw new Error(`Invalid arguments: unknown property "${key}"`);
    }
  }
}

export async function callTool(name, args) {
  if (name !== 'inventory_search') {
    throw new Error(`Unknown tool: ${name}`);
  }
  const a = args || {};
  validateInventorySearchArgs(a);
  const needle = a.query.toLowerCase();
  const matches = products.filter(p => p.name.toLowerCase().includes(needle));
  const limited = typeof a.limit === 'number' ? matches.slice(0, a.limit) : matches;
  const text = limited.length === 0
    ? 'No matching products found.'
    : limited.map(p => `${p.id}: ${p.name}`).join('\n');
  return {
    content: [
      { type: 'text', text }
    ]
  };
}
